// MongoDB Shell (mongosh)
db.schueler.insertOne({
  name: "Anna", klasse: "5AHIF",
  noten: [ { fach: "DBI", note: 1 },
           { fach: "AM",  note: 2 } ]
})

db.schueler.find(
  { "noten.fach": "DBI" },
  { name: 1, _id: 0 })

// Bedingungen auf DASSELBE
// Listenelement: $elemMatch
db.schueler.find({ noten:
  { $elemMatch: { fach: "DBI",
      note: { $lte: 2 } } } })

// Neo4j (Cypher)
MATCH (a:Person {name: 'Anna'})
  -[:FREUND]->(:Person)
  -[:FREUND]->(c:Person)
WHERE c <> a AND NOT EXISTS {
  (a)-[:FREUND]->(c) }
RETURN DISTINCT c.name;

# Python
freunde = {
  "Anna": ["Ben", "Cem"],
  "Ben":  ["Anna", "Dora"],
  "Cem":  ["Anna", "Dora", "Emil"],
  "Dora": ["Ben", "Cem"],
  "Emil": ["Cem"]}
fof = {c for b in freunde["Anna"]
         for c in freunde[b]}
fof -= set(freunde["Anna"]) | {"Anna"}
print(sorted(fof))  # ['Dora', 'Emil']
